228: async function assertCanImport(userId) {
229:   // ADMIN and DEVELOPER are account-level roles carried by "user".role_id, not
230:   // rows in person_has_role (which holds TEACHER/STUDENT); read the account's
231:   // role the same way every other gate in the app does.
232:   const rows = await rowsOf(
