251: function normalizeTxResult(result) {
252:   if (Array.isArray(result)) return result
253:   return result?.data || []
254: }
255: 
256: function insertSql(table, row) {
257:   const columns = Object.keys(row)
258:   const placeholders = columns.map((_, index) => `$${index + 1}`)
259:   return {
260:     sql: `INSERT INTO ${table} (${columns.join(', ')}) VALUES (${placeholders.join(', ')}) ON CONFLICT DO NOTHING RETURNING *`,
261:     values: columns.map((column) => row[column])
262:   }
263: }
264: 
265: function liveWriter(tx) {
266:   const run = async (sql, params = []) => normalizeTxResult(await tx(sql, params))
267:   return {
268:     run,
269:     async insert(table, row) {
270:       const { sql, values } = insertSql(table, row)
271:       const rows = await run(sql, values)
272:       return rows[0] || null
273:     },
274:     async link(table, row) {
275:       const { sql, values } = insertSql(table, row)
276:       await run(sql, values)
277:     },
278:     async updatePersonProfile(personId, profile) {
279:       await run(
280:         `UPDATE person
281:             SET person_birthdate = COALESCE($2::date, person_birthdate),
282:                 person_sex = COALESCE($3, person_sex)
283:           WHERE person_id = $1`,
284:         [personId, profile.birthdate, profile.sex]
285:       )
286:     }
287:   }
288: }
