400: async function importSessionTypes(ctx) {
401:   const stat = stepStat(ctx, 'sessionTypes', 'Session types', 'study_session_type', 'study_session_type')
402:   for (const row of tableRows(ctx.parsed, 'study_session_type')) {
403:     countRead(stat)
404:     const labelEn = text(pick(row, 'STUDY_SESSION_TYPE_LABEL_EN'))
405:     const code = text(pick(row, 'STUDY_SESSION_TYPE_CODE')) || slug(labelEn, 'TYPE')
406:     const existing = ctx.lookups.sessionTypes.get(keysOf(code))
407:     let id = existing?.STUDY_SESSION_TYPE_ID ?? null
408:     if (!id) {
409:       const inserted = await ctx.writer.insert('study_session_type', {
410:         study_session_type_code: truncate(code, 20),
411:         study_session_type_label_en: truncate(labelEn || code, 100),
412:         study_session_type_label_ar: truncate(pick(row, 'STUDY_SESSION_TYPE_LABEL_AR'), 100),
413:         study_session_type_label_fr: truncate(pick(row, 'STUDY_SESSION_TYPE_LABEL_FR'), 100),
414:       })
415:       id = insertedId(inserted, 'study_session_type_id')
416:       if (id) ctx.lookups.sessionTypes.set(keysOf(code), { STUDY_SESSION_TYPE_ID: id })
417:     }
418:     if (id) {
419:       ctx.ids.sessionType.set(String(pick(row, 'STUDY_SESSION_TYPE_ID')), id)
420:       stat.inserted += 1
421:     } else {
422:       countSkip(ctx, stat, REASONS.missingType)
423:     }
424:   }
425: }
