```js
async function runMapping(parsed, lookups, writer, stepIds, { isolate = false } = {}) {
  const ctx = makeContext(parsed, lookups, writer)
  const selected = new Set(stepIds == null ? ALL_STEP_IDS : stepIds)
  const completed = new Set()
  const failed = new Map()

  for (const step of STEPS) {
    if (!selected.has(step.id)) continue
    const blockedBy = step.dependsOn.find((dep) => selected.has(dep) && !completed.has(dep))
    if (blockedBy) {
      failed.set(step.id, { id: step.id, label: step.label, code: 'dependencyFailed', step: blockedBy })
      continue
    }
    const snapshot = snapshotContext(ctx)
    try {
      if (writer.beginStep) await writer.beginStep(step.id)
      await step.run(ctx)
      if (writer.endStep) await writer.endStep(step.id)
      completed.add(step.id)
    } catch (error) {
      if (writer.rollbackStep) await writer.rollbackStep(step.id)
      restoreContext(ctx, snapshot)
      failed.set(step.id, { id: step.id, label: step.label, code: 'runtimeError', message: error.message })
    }
  }
  ...
}
```
