// per person from a range of its own. The person table is required to be empty
// before an import (see runLegacyImport), so a minted id cannot land on a
// person that is already there.
const IMPORT_PERSON_ID_BASE = 900000000000

function mintPersonId(ctx) {
  ctx.mintedPersonId += 1
  return IMPORT_PERSON_ID_BASE + ctx.mintedPersonId
}

