async function clearTargets(tx, stepIds) {
  const targets = new Set()
  for (const id of stepIds) {
    for (const table of STEP_BY_ID.get(id)?.targets || []) targets.add(table)
  }
  const cleared = []
  for (const table of CLEAR_ORDER) {
    if (!targets.has(table)) continue
    try {
      const result = await tx(`DELETE FROM ${table}`)
      cleared.push({ table, count: Number(result?.rowCount || 0) })
    } catch (error) {
      if (error?.code === '23503') {
        throw new Error(
          `Replace could not clear \`${table}\` because other records still reference it. ` +
          'Select the tables that depend on it too, or import with merge mode instead.'
        )
      }
      throw error
    }
  }
  return cleared
}

