const stubDb = `
export const __sql = []
const isAuth = (sql) => /FROM "user" u/.test(sql)
export async function query(sql, params = []) {
  __sql.push({ kind: 'query', sql })
  if (isAuth(sql)) return { data: [{ ONE: 1 }] }
  return { data: [] }
}
export async function withTransaction(fn) {
  const tx = async (sql, params = []) => {
    __sql.push({ kind: 'tx', sql })
